with cleaned as (select id, email, country, city, segment, signup_date, is_active, upper(country) as country_upper, last_day(signup_date) as signup_date_month_end from customers where is_active = true) select s.*, x.start_date from cleaned s join lateral (select c.start_date from subscriptions c where c.customer_id = s.id and c.end_date <= s.signup_date order by c.end_date desc, c.id desc limit 1) x on true
